// Welche Abhängigkeitsrichtung ist korrekt?

class NutzerRepositoryImpl(
    private val remoteSource: NutzerRemoteSource,
    private val localSource: NutzerLocalSource
) : NutzerRepository {
    override suspend fun getNutzer(id: Int): Result<Nutzer> {
        return localSource.getNutzer(id)?.let { Result.success(it) }
            ?: remoteSource.getNutzer(id).also {
                it.getOrNull()?.let { nutzer -> localSource.speichere(nutzer) }
            }
    }
}

