class EventBus {
    private val listener = mutableMapOf<String, MutableList<(Any) -> Unit>>()

    fun subscribe(event: String, handler: (Any) -> Unit) {
        listener.getOrPut(event) { mutableListOf() }.add(handler)
    }

    fun publish(event: String, data: Any) {
        listener[event]?.forEach { it(data) }
    }
}

