class MeinProcessor : SymbolProcessor {
    override fun process(resolver: Resolver): List<KSAnnotated> {
        val deferred = mutableListOf<KSAnnotated>()
        resolver.getSymbolsWithAnnotation("com.mein.Ann")
            .forEach {
                if (it.validate()) generiere(it)
                else deferred.add(it)
            }
        return deferred
    }
}

class MeinProcessor(env: SymbolProcessorEnvironment) : SymbolProcessor {
    val codegen = env.codeGenerator

    fun generiere(klasse: KSClassDeclaration) {
        val file = codegen.createNewFile(
            dependencies = Dependencies(false, klasse.containingFile!!),
            packageName = klasse.packageName.asString(),
            fileName = "${klasse.simpleName.asString()}Generated"
        )
        file.write("// Generated code".toByteArray())
    }
}

class ProcessorProvider : SymbolProcessorProvider {
    override fun create(env: SymbolProcessorEnvironment): ___ {
        return MeinProcessor(env)
    }
}

// Clean Architecture:
// UI → ViewModel → UseCase → Repository → DataSource

interface NutzerRepository {
    suspend fun getNutzer(id: Int): Result<Nutzer>
}

class GetNutzerUseCase(private val repo: NutzerRepository) {
    suspend operator fun invoke(id: Int) = repo.getNutzer(id)
}

class NutzerViewModel(
    private val getNutzer: GetNutzerUseCase
) : ViewModel() {
    private val _state = MutableStateFlow<UiState>(UiState.Laden)
    val state = _state.asStateFlow()

    fun lade(id: Int) {
        viewModelScope.launch {
            _state.value = when (val r = getNutzer(id)) {
                is Success -> UiState.Bereit(r.value)
                is Failure -> UiState.Fehler(r.error)
            }
        }
    }
}

class NutzerRepositoryImpl(
    private val api: NutzerApi,
    private val db: NutzerDao
) : NutzerRepository {
    override suspend fun getNutzer(id: Int): Result<Nutzer> = runCatching {
        db.getNutzer(id) ?: api.getNutzer(id).also { ___(it) }
    }
    private suspend fun cacheNutzer(n: Nutzer) = db.___(n)
}

sealed interface UiState {
    object Laden : UiState
    data class Bereit(val nutzer: Nutzer) : UiState
    data class Fehler(val nachricht: String) : UiState
}

// In Composable:
when (state) {
    is UiState.Laden -> Ladeindikator()
    is UiState.Bereit -> NutzerAnzeige(state.nutzer)
